<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { detalleExpediente,listarExpedientes,registrarExpediente,type Expediente,type OpcionesExpediente } from '../services/expedientes'
const empty:OpcionesExpediente={tipos:[],subtipos:[],estados:[],juzgados:[],oficinas:[]}
const rows=ref<Expediente[]>([]),options=ref(empty),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),detail=ref<Expediente|null>(null),file=ref<File|null>(null)
const filters=reactive({criterio:'',tipo:'',estado:'',desde:'',hasta:'',page:1})
const form=reactive({numero_expediente:'',tipo_expediente_id:'',subtipo_expediente_id:'',fecha_inicio:new Date().toISOString().slice(0,10),numero_expediente_judicial:'',juzgado_id:'',oficina_id:'',cuantia_total:'',monto_sentencia_total:'',observaciones:''})
const subtypes=computed(()=>options.value.subtipos.filter(x=>!x.tipo_expediente_id||String(x.tipo_expediente_id)===String(form.tipo_expediente_id)))
const selectedType=computed(()=>options.value.tipos.find(x=>String(x.id)===String(form.tipo_expediente_id)))
const isJudicial=computed(()=>selectedType.value?.codigo?.toUpperCase()==='JUD')
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarExpedientes(filters);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;options.value=r.options}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(){Object.assign(form,{numero_expediente:'',tipo_expediente_id:'',subtipo_expediente_id:'',fecha_inicio:new Date().toISOString().slice(0,10),numero_expediente_judicial:'',juzgado_id:'',oficina_id:'',cuantia_total:'',monto_sentencia_total:'',observaciones:''});file.value=null;modal.value=true}
async function save(){if(!form.numero_expediente||!form.tipo_expediente_id||!form.subtipo_expediente_id||!form.fecha_inicio||!file.value){error.value='Complete los datos obligatorios y adjunte el PDF principal.';return}if(isJudicial.value&&(!form.numero_expediente_judicial||!form.juzgado_id)){error.value='Para un expediente judicial indique el número judicial y el juzgado.';return}const data=new FormData();Object.entries(form).forEach(([k,v])=>{if(v!=='')data.append(k,String(v))});data.append('archivo_principal',file.value);saving.value=true;error.value='';try{await registrarExpediente(data);modal.value=false;success.value='Expediente registrado correctamente.';await load(1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function show(item:Expediente){try{detail.value=await detalleExpediente(item.id)}catch(e){error.value=message(e)}}
function choose(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]||null}
function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / MAT / Expedientes</nav><header class="hero"><div class="mark">EX</div><div><small>MAT · LEGAL</small><h1>Gestión de expedientes</h1><p>Registro y seguimiento centralizado de expedientes legales.</p></div><strong>{{total}} expedientes</strong><button @click="open">+ Nuevo expediente</button></header>
<p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p>
<section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Número, centro arbitral o entidad" @keyup.enter="load(1)"></label><label>Tipo<select v-model="filters.tipo"><option value="">Todos</option><option v-for="x in options.tipos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Estado<select v-model="filters.estado"><option value="">Todos</option><option v-for="x in options.estados" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Desde<input v-model="filters.desde" type="date"></label><label>Hasta<input v-model="filters.hasta" type="date"></label><button @click="load(1)">Consultar</button></section>
<div v-if="loading" class="empty">Cargando expedientes…</div><div v-else-if="!rows.length" class="empty">No se encontraron expedientes.</div><section v-else class="table"><header><span>Expediente</span><span>Tipo / subtipo</span><span>Inicio</span><span>Oficina / juzgado</span><span>Etapa</span><span>Estado</span><span>Contenido</span><span></span></header><article v-for="item in rows" :key="item.id"><div><b>{{item.numero_expediente}}</b><small>{{item.numero_expediente_judicial}}</small></div><div><b>{{item.tipo}}</b><small>{{item.subtipo}}</small></div><time>{{item.fecha_inicio}}</time><span>{{item.juzgado||item.oficina||'—'}}</span><span>{{item.etapa||'Sin etapa'}}</span><em :style="{borderColor:item.estado_color}">{{item.estado||'Activo'}}</em><small>{{item.partes_count||0}} partes · {{item.adjuntos_count||0}} archivos · {{item.alertas_count||0}} alertas</small><button @click="show(item)">Ver ficha</button></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>NUEVO REGISTRO</small><h2>Registrar expediente</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Número interno *<input v-model.trim="form.numero_expediente"></label><label>Fecha de inicio *<input v-model="form.fecha_inicio" type="date"></label><label>Tipo *<select v-model="form.tipo_expediente_id" @change="form.subtipo_expediente_id=''" ><option value="">Seleccione</option><option v-for="x in options.tipos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Subtipo *<select v-model="form.subtipo_expediente_id"><option value="">Seleccione</option><option v-for="x in subtypes" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Oficina<select v-model="form.oficina_id"><option value="">Sin asignar</option><option v-for="x in options.oficinas" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label></div><div v-if="isJudicial" class="judicial"><h3>Datos judiciales obligatorios</h3><div class="grid"><label>Número judicial *<input v-model.trim="form.numero_expediente_judicial"></label><label>Juzgado *<select v-model="form.juzgado_id"><option value="">Seleccione</option><option v-for="x in options.juzgados" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Cuantía total<input v-model="form.cuantia_total" type="number" min="0" step="0.01"></label><label>Monto de sentencia<input v-model="form.monto_sentencia_total" type="number" min="0" step="0.01"></label></div></div><label>Observaciones<textarea v-model.trim="form.observaciones" rows="3"></textarea></label><label>Documento principal PDF *<input type="file" accept="application/pdf" @change="choose"><small>Máximo 25 MB.</small></label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Registrando…':'Registrar expediente'}}</button></footer></form></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal detail"><header><div><small>FICHA DEL EXPEDIENTE</small><h2>{{detail.numero_expediente}}</h2><p>{{detail.tipo}} · {{detail.subtipo}}</p></div><button @click="detail=null">×</button></header><div class="summary"><div><b>{{detail.estado||'Activo'}}</b><span>Estado</span></div><div><b>{{detail.etapa||'—'}}</b><span>Etapa actual</span></div><div><b>{{detail.partes?.length||0}}</b><span>Partes</span></div><div><b>{{detail.adjuntos?.length||0}}</b><span>Adjuntos</span></div></div><h3>Partes procesales</h3><div class="list"><p v-if="!detail.partes?.length">Sin partes registradas.</p><div v-for="x in detail.partes" :key="x.id"><b>{{x.nombre}}</b><span>{{x.tipo_parte}} · {{x.documento||'Sin documento'}}</span></div></div><h3>Documentos adjuntos</h3><div class="list"><p v-if="!detail.adjuntos?.length">Sin adjuntos registrados.</p><div v-for="x in detail.adjuntos" :key="x.id"><b>{{x.descripcion||x.nombre_original}}</b><span>{{x.nombre_original}} · {{x.tamano_kb||0}} KB</span></div></div><h3>Historial de etapas</h3><div class="list"><p v-if="!detail.historial?.length">Sin movimientos registrados.</p><div v-for="x in detail.historial" :key="x.id"><b>{{x.etapa}}</b><span>{{x.fecha_inicio}} {{x.fecha_fin?'→ '+x.fecha_fin:''}}</span></div></div><footer><button class="clear" @click="detail=null">Cerrar</button></footer></section></div></div></template>
<style scoped>
.page{--accent:#596a7b;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:700}.hero small,.modal small{color:var(--accent);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.35rem}.hero p,.modal header p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.hero button,.filters button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.56rem}.flash{padding:10px;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.63rem}.flash.error{color:#a13f43;background:#fff0f0}.filters{margin-top:13px;padding:12px;display:flex;align-items:end;gap:7px;border-radius:9px;background:#fff}.filters label{flex:1;font-size:.53rem}.filters label:first-child{flex:2}input,select,textarea{width:100%;padding:8px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.6rem}.table{margin-top:13px;border-radius:9px;background:#fff;overflow:hidden}.table>header,.table>article{padding:10px 12px;display:grid;grid-template-columns:1.1fr 1.2fr 80px 1.2fr 1fr 85px 1.1fr 65px;align-items:center;gap:8px}.table>header{color:#fff;background:var(--accent);font-size:.5rem;font-weight:700}.table>article{border-bottom:1px solid #edf0f2;font-size:.54rem}.table small{display:block;color:#7d898f}.table em{padding:4px;border:1px solid #cbd3d8;border-radius:10px;font-style:normal;text-align:center}.table article>button{border:0;color:var(--accent);background:none;font-size:.52rem;font-weight:700}.empty{margin-top:13px;padding:45px;text-align:center;background:#fff;font-size:.63rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.55rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,800px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:10px;font-size:.56rem}.modal label small{display:block;margin-top:4px;color:#89959b}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.judicial{margin:4px 0 12px;padding:12px;border-left:3px solid #b68235;background:#fbf7ef}.modal h3{font-size:.65rem}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.summary{margin:14px 0;display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.summary div{padding:11px;text-align:center;border-radius:7px;background:#f0f3f5}.summary b,.summary span{display:block;font-size:.55rem}.list div{padding:8px;border-bottom:1px solid #e8ecee;font-size:.56rem}.list div b,.list div span{display:block}.list div span,.list>p{color:#7d898f}.detail{width:min(100%,900px)}@media(max-width:900px){.table>header{display:none}.table>article{grid-template-columns:1fr 1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}.grid,.summary{grid-template-columns:1fr 1fr}}@media(max-width:520px){.table>article,.grid{grid-template-columns:1fr}}
</style>
